Error: LLM output not valid JSON. Raw output:
{
    "selected_variables": [
        {
            "name": "perceived_public_opinion"
        },
        {
            "name": "social_connection_strength"
        },
        {
            "name": "fear_of_isolation"
        },
        {
            "name": "opinion_stability"
        }
    ],
    "composite_variables": [
        {
            "name": "decision_influence",
            "composed_from": ["perceived_public_opinion", "social_connection_strength"],
            "conceptual_meaning": "the combined effect of perceived public opinion and social connection strength on the decision to speak or remain silent",
            "composition_logic": "stronger perceived public opinion combined with stronger social connections increases the likelihood of speaking up; weak public opinion or weak connections lowers it",
            "data_type": "float",
            "pseudocode": "decision_influence = beta * perceived_public_opinion + (1 - beta) * social_connection_strength",
            "update_rule": "updated each timestep based on current perceived_public_opinion and social_connection_strength from the agent's neighbors"
        }
    ],
    "interaction_analysis": [
        {
            "behavioral_decision": "decide to speak or remain silent",
            "reasoning": "The decision is influenced by the perceived public opinion and the strength of social connections, while fear of isolation and opinion stability characterize the agent's emotional state.",
            "merge_decisions": "perceived_public_opinion and social_connection_strength merge into the composite variable decision_influence, as they both serve to influence the likelihood of agent expression collectively."
        }
    ],
    "decision_rules": [
        {
            "behavioral_decision": "decide to speak-up or stay silent",
            "outcome_variable": "agent.is_speaking",
            "signal_computation": [
                {
                    "signal_name": "decision_influence",
                    "composed_from": ["perceived_public_opinion", "social_connection_strength"],
                    "expression": "decision_influence = beta * perceived_public_opinion + (1 - beta) * social_connection_strength",
                    "parameter": "beta — controls the relative weight of perceived public opinion vs social connection strength"
                }
            ],
            "rule_pseudocode": 
                "IF decision_influence > influence_threshold:
                    agent.is_speaking = True
                ELIF fear_of_isolation > isolation_threshold:
                    agent.is_speaking = False  # override: high fear of isolation leads them to remain silent
                ELSE:
                    agent.is_speaking = False",
            "parameters": [
                {
                    "name": "beta",
                    "role": "balances the influence of perceived public opinion and social connection strength in decision making",
                    "default": "0.5",
                    "calibratable": true
                },
                {
                    "name": "influence_threshold",
                    "role": "minimum influence level required for agent to decide to speak",
                    "default": "0.5",
                    "calibratable": true
                },
                {
                    "name": "isolation_threshold",
                    "role": "fear of isolation level above which agent opts to stay silent regardless of influence",
                    "default": "0.7",
                    "calibratable": true
                }
            ],
            "variables_used": ["perceived_public_opinion", "social_connection_strength", "fear_of_isolation", "decision_influence"],
            "explanation": "The agent computes the decision_influence based on perceived public opinion and social connection strength. If this influence crosses a certain threshold, the agent will choose to speak up. However, if fear of isolation is strong enough, it overrides the decision to speak. This captures the nuanced dynamics of social interactions in the context of the spiral of silence phenomenon."
        }
    ]
}
